using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageTargetFrameworkSymbolTests
{
    private const string AttributeName = "System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverageAttribute";

    private const string Source = """
        using MessagePack;

        namespace MyNs
        {
            [GeneratedMessagePackResolver]
            partial class MyResolver { }

            [MessagePackObject]
            public class IntKeyObject
            {
                [Key(0)]
                public int A { get; set; }
            }
        }
        """;

    [Theory]
    [InlineData("NETSTANDARD2_0")]
    [InlineData("NETFRAMEWORK")]
    public async Task GeneratedCodeIsDecoratedWhenTargetFrameworkSymbolDefined(string symbol)
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest, preprocessorSymbols: new[] { symbol });
        ImmutableArray<MetadataReference> framework = await Microsoft.CodeAnalysis.Testing.ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> references = Enumerable.Concat<MetadataReference>(framework, ReferencesHelper.GetReferences(ReferencesSet.MessagePack)).ToList();
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsCoverageTfmTestAssembly",
            new[] { CSharpSyntaxTree.ParseText(Source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator()).WithUpdatedParseOptions(parseOptions);
        driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> generatorDiagnostics);

        Assert.Empty(generatorDiagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));
        Assert.Empty(output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error));

        HashSet<SyntaxTree> original = new HashSet<SyntaxTree>(compilation.SyntaxTrees);
        HashSet<SyntaxTree> generated = new HashSet<SyntaxTree>(output.SyntaxTrees.Where(t => !original.Contains(t)));

        List<INamedTypeSymbol> formatters = AllTypes(output.Assembly.GlobalNamespace)
            .Where(t => t.DeclaringSyntaxReferences.Any(r => generated.Contains(r.SyntaxTree))
                && t.AllInterfaces.Any(i => i.OriginalDefinition.ToDisplayString() == "MessagePack.Formatters.IMessagePackFormatter<T>"))
            .ToList();
        Assert.NotEmpty(formatters);
        Assert.Empty(formatters.Where(t => !HasAttribute(t)).Select(t => t.ToDisplayString()));

        INamedTypeSymbol? resolver = output.GetTypeByMetadataName("MyNs.MyResolver");
        Assert.NotNull(resolver);
        Assert.True(HasAttribute(resolver!), "The generated resolver should be decorated with ExcludeFromCodeCoverage on every target.");
    }

    private static bool HasAttribute(INamedTypeSymbol type)
        => type.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == AttributeName);

    private static IEnumerable<INamedTypeSymbol> AllTypes(INamespaceOrTypeSymbol container)
    {
        foreach (ISymbol member in container.GetMembers())
        {
            if (member is INamespaceSymbol ns)
            {
                foreach (INamedTypeSymbol t in AllTypes(ns))
                {
                    yield return t;
                }
            }
            else if (member is INamedTypeSymbol type)
            {
                yield return type;
                foreach (INamedTypeSymbol nested in AllTypes(type))
                {
                    yield return nested;
                }
            }
        }
    }
}
